with unpacked as (select id, service, log_ts, status_code, coalesce(context['version'], 'none') as version_or_default, context['version'] as version from app_logs) select id, service, log_ts, version_or_default, avg(status_code) over (partition by service order by status_code, id rows between 6 preceding and current row) status_code_avg_6, round(status_code / sum(status_code) over (partition by service), 4) status_code_share, lead(status_code, 1) over (order by log_ts, id) next_status_code from unpacked;
